import math
import unittest

from solution import canvas_pixels


class CanvasPixelsTests(unittest.TestCase):
    def test_rounds_products_to_nearest_integer(self):
        self.assertEqual(canvas_pixels(2.4, 3.6, 1), (2, 4))
        self.assertEqual(canvas_pixels(5, 7, 2), (10, 14))

    def test_exact_halves_round_upward(self):
        self.assertEqual(canvas_pixels(2.5, 3.5, 1), (3, 4))
        self.assertEqual(canvas_pixels(1, 5, 0.5), (1, 3))

    def test_very_small_positive_products_may_round_to_zero(self):
        self.assertEqual(canvas_pixels(0.1, 0.49, 1), (0, 0))
        self.assertEqual(canvas_pixels(0.01, 1, 10), (0, 10))

    def test_rejects_invalid_types_including_booleans(self):
        valid = (1, 1, 1)
        for index, malformed in enumerate((True, "1", None, complex(1, 0))):
            for position in range(3):
                arguments = list(valid)
                arguments[position] = malformed
                with self.subTest(index=index, position=position):
                    with self.assertRaises(TypeError):
                        canvas_pixels(*arguments)

    def test_rejects_nonpositive_and_nonfinite_numbers(self):
        for malformed in (0, -1, float("inf"), float("-inf"), float("nan")):
            for position in range(3):
                arguments = [1, 1, 1]
                arguments[position] = malformed
                with self.subTest(value=malformed, position=position):
                    with self.assertRaises(ValueError):
                        canvas_pixels(*arguments)

    def test_returns_integer_tuple(self):
        result = canvas_pixels(1.2, 2.2, 2)
        self.assertEqual(result, (2, 4))
        self.assertIs(type(result), tuple)
        self.assertTrue(all(type(value) is int for value in result))


if __name__ == "__main__":
    unittest.main()

